package org.racedaydreams.domain.strength;

import java.util.List;

/** Original, movement-specific catalogue guidance. Unknown/custom movements never inherit a pose. */
final class CatalogueTechniqueGuides {
    private CatalogueTechniqueGuides() {}

    static TechniqueGuide forExercise(String id) {
        return switch (id) {
            case "high-bar-squat" -> g("squat", "Support the bar on your upper traps, below the neck; set rack safeties and brace.", "Bend hips and knees together, keeping feet planted; stand without losing trunk control.", "Quadriceps and glutes", "Keep elbows and bar stable|Let knees follow toes|Choose a controlled depth", "Bar on the neck|Heels lifting|Bouncing out of the bottom", "Goblet Squat|Leg Press");
            case "low-bar-squat" -> g("squat", "Support the bar across the rear shoulders, below the upper traps; grip securely and set safeties.", "Sit hips back as knees bend; maintain the braced torso angle, then stand through your feet.", "Glutes, quadriceps and trunk", "Keep bar securely supported|Brace before bending|Keep the whole foot down", "Bar slipping down the back|Losing trunk control|Rising hips without the chest", "High-Bar Squat|Leg Press");
            case "pause-squat" -> g("squat", "Set rack safeties, support the bar across the upper back and brace before lowering.", "Squat to a controllable depth; pause briefly while staying braced, then stand smoothly.", "Quadriceps and glutes", "Maintain tension during the pause|Keep feet planted|Use a lighter manageable load", "Relaxing at the bottom|Bouncing instead of pausing|Holding a pause beyond control", "Back Squat|Goblet Squat");
            case "box-squat" -> g("squat", "Place a stable box behind you; support the bar on the upper back and set safeties.", "Lower onto the box with control, keeping your trunk braced; stand without rocking backwards.", "Quadriceps, glutes and trunk", "Check box stability|Keep feet planted|Stay braced at contact", "Dropping onto the box|Rocking to gain momentum|Using an unsuitable box height", "Back Squat|Goblet Squat");
            case "hack-squat" -> g("squat", "Adjust the machine, support your back under the shoulder pads and plant both feet on the platform.", "Release the safety as instructed; bend knees and hips, then press the carriage up without snapping knees straight.", "Quadriceps and glutes", "Keep back and pelvis supported|Use the machine stops|Lower through a comfortable range", "Hips lifting off the pad|Locking knees forcefully|Releasing safeties before stable", "Leg Press|Goblet Squat");
            case "pendulum-squat" -> g("squat", "Set the pendulum machine stops; settle under its shoulder pads with feet stable on the platform.", "Lower with the swinging carriage, keeping the trunk supported; press back to the start under control.", "Quadriceps and glutes", "Check the starting latch|Maintain foot contact|Follow the machine's comfortable arc", "Bouncing at the bottom|Losing pad contact|Using a range you cannot reverse", "Hack Squat|Leg Press");
            case "belt-squat" -> g("squat", "Secure the machine belt around your hips and connect its resistance below you; hold the balance handles.", "Bend hips and knees with feet stable, then stand; keep the belt load centred beneath your pelvis.", "Quadriceps and glutes", "Check belt and connection|Keep feet supported|Use handles for balance", "Unsecured belt or chain|Leaning on handles to lift|Bouncing beyond control", "Goblet Squat|Leg Press");
            case "zercher-squat" -> g("squat", "Set safeties and cradle the bar in bent elbow creases in front of your trunk; brace securely.", "Lower into a controlled squat with the bar close, then stand without letting it roll away.", "Quadriceps, glutes and trunk", "Keep the bar close|Use a comfortable load and padding|Keep feet planted", "Bar rolling out of the elbows|Rounding uncontrollably|Loading beyond a secure hold", "Goblet Squat|Front Squat");
            case "smith-machine-squat" -> g("squat", "Set the Smith machine safety stops; place the bar on the upper back and find a stable foot position.", "Unrack securely, squat along the fixed bar path, then stand and re-engage the hooks deliberately.", "Quadriceps and glutes", "Check the hooks and stops|Keep feet planted|Use a comfortable position for the rail path", "Unfamiliar release mechanism|Forcing an uncomfortable stance|Bouncing into the stops", "Hack Squat|Goblet Squat");
            case "single-leg-press" -> g("squat", "Sit supported with one foot on the platform and the other safely clear of the moving carriage.", "Bend the working leg through a comfortable range, then press without locking the knee; change sides as prescribed.", "Quadriceps and glutes", "Keep pelvis supported|Use a lighter single-leg load|Keep the other leg clear", "Pelvis twisting|Locking the knee|Pushing with the resting leg", "Leg Press|Step-Up");
            case "sissy-squat" -> g("squat", "Stand beside a stable support and hold it for balance; start without added load.", "Allow knees forwards as your aligned torso and thighs lean back; use a small controlled range and return.", "Quadriceps", "Use secure hand support|Keep the movement comfortable|Start with a short range", "Dropping backwards|Forcing knee discomfort|Letting go before balanced", "Leg Extension|Goblet Squat");
            case "sumo-deadlift" -> g("hinge", "Take a wide comfortable stance with toes turned out; grip the bar inside your knees and brace.", "Push through the floor and extend hips and knees together; finish tall, then lower the bar close under control.", "Glutes, quadriceps and posterior chain", "Keep knees following toes|Keep the bar close|Brace before each lift", "Jerking from the floor|Leaning backwards at the finish|Choosing an excessively wide stance", "Conventional Deadlift|Trap-Bar Deadlift");
            case "single-leg-rdl" -> g("hinge", "Stand balanced on one leg, holding manageable dumbbells; soften the working knee.", "Hinge the hips back as the free leg reaches behind; keep the pelvis level, then return slowly.", "Hamstrings, glutes and trunk", "Keep the hips level|Reach back rather than down|Use support if balance limits control", "Twisting the pelvis open|Rounding to reach lower|Rushing the return", "Romanian Deadlift|Hip Thrust");
            case "good-morning" -> g("hinge", "Support a light bar across the upper back, set rack safeties and brace with softly bent knees.", "Push hips back to hinge the trunk forwards, keeping the bar on your back; extend the hips to stand.", "Hamstrings, glutes and back extensors", "Start light|Keep a steady back position|Stop at a controlled hinge depth", "Bending mainly through the back|Using excessive load|Turning it into a deep squat", "Romanian Deadlift|Cable Pull-Through");
            case "box-step-up" -> g("split", "Place your whole working foot on a stable box; hold manageable dumbbells if using load.", "Stand through the foot on the box, then step down slowly; change sides as prescribed.", "Quadriceps and glutes", "Keep the box stable|Use the working leg|Control the step down", "Jumping from the floor|Landing heavily|Using a box too high for control", "Step-Up|Reverse Lunge");
            case "row" -> g("row", "Hold a barbell with hips hinged back, knees softly bent and trunk braced.", "Pull the bar toward the lower ribs without standing up; lower until arms extend under control.", "Upper back, lats and elbow flexors", "Maintain the trunk angle|Draw elbows back|Lower smoothly", "Heaving with the hips|Rounding under load|Pulling beyond a comfortable range", "Barbell Row|Seated Cable Row");
            case "bodyweight-squat" -> g("squat", "Stand with feet comfortably apart and arms free for balance; no added load is needed.", "Bend hips and knees through a comfortable depth, keeping feet flat, then stand smoothly.", "Quadriceps and glutes", "Keep feet supported|Let knees follow toes|Choose a controlled range", "Heels lifting|Dropping into the bottom|Forcing an uncomfortable depth", "Goblet Squat|Step-Up");
            case "reverse-lunge-bodyweight" -> g("split", "Stand tall with space behind you and hands free for balance.", "Step one foot back, lower both knees under control, then push through the front foot to stand.", "Quadriceps and glutes", "Keep the front foot flat|Use a stable stance width|Move slowly", "Stepping on a tightrope|Pushing mostly from the rear foot|Rushing the return", "Step-Up|Bodyweight Squat");
            case "single-leg-calf-raise-bodyweight" -> g("calf", "Hold a stable support and place one forefoot on a secure low step; lift the other foot clear.", "Lift the working heel, pause briefly, then lower slowly through a comfortable ankle range; change sides.", "Calves", "Keep balance support|Keep the working knee steady|Control both directions", "Bouncing|Rolling the ankle outwards|Dropping the heel beyond comfort", "Calf Raise|Seated Calf Raise");
            case "wall-sit" -> g("hold", "Place your back against a stable wall and feet a comfortable distance forwards.", "Slide into a manageable bent-knee position; breathe steadily and rise to finish before control fades.", "Quadriceps and glutes", "Keep feet flat|Use a comfortable knee angle|Breathe throughout", "Sliding feet away|Holding your breath|Holding through discomfort", "Bodyweight Squat|Leg Press");
            case "weighted-wall-sit" -> g("hold", "Set up against a wall with feet flat; steady one manageable plate securely across the thighs.", "Hold a comfortable bent-knee position while breathing; remove the plate safely before standing.", "Quadriceps and glutes", "Secure the load|Choose a manageable hold|Keep feet planted", "An unstable plate|Holding through discomfort|Standing abruptly with loose load", "Wall Sit|Goblet Squat");
            case "weighted-side-plank" -> g("hold", "Support on one forearm with elbow under shoulder; steady a small plate securely over the upper hip.", "Lift into a controlled side-plank line and breathe; lower before removing the load, then change sides.", "Trunk stabilisers", "Keep load secure|Keep hips aligned|Use an unloaded hold if unsure", "Letting the plate slide|Twisting the trunk|Holding beyond control", "Side Plank|Pallof Press");
            case "hanging-knee-raise" -> g("core", "Grip a secure bar and begin in a controlled hang with feet clear of the floor.", "Bend and raise the knees toward your trunk without swinging; lower slowly to a steady hang.", "Abdominals, hip flexors and grip", "Begin from stillness|Lift within control|Lower smoothly", "Kicking to start|Swinging the trunk|Losing grip to gain repetitions", "Dead Bug|Hanging Leg Raise");
            case "hanging-leg-raise" -> g("core", "Begin hanging from a secure bar with a steady grip and softly extended legs.", "Raise the legs forwards toward horizontal within your controlled range; lower without swinging.", "Abdominals, hip flexors and grip", "Keep the hang steady|Use a manageable range|Control the lowering", "Using a swing|Forcing straight knees|Dropping the legs abruptly", "Hanging Knee Raise|Dead Bug");
            case "toes-to-bar" -> g("core", "Take a secure overhead grip and begin from a controlled hang; use a knee raise if needed.", "Curl the pelvis and raise the legs toward the bar within your ability; lower with control and reset.", "Abdominals, hip flexors and grip", "Progress from simpler raises|Keep a secure grip|Use a controlled return", "Forcing range with momentum|Dropping from a weak grip|Losing trunk control", "Hanging Knee Raise|Hanging Leg Raise");
            case "cable-crunch" -> g("core", "Kneel facing a high pulley with rope ends held beside your head; choose a light manageable load.", "Bring ribs toward pelvis by curling the trunk, then return slowly; keep the hips fairly steady.", "Abdominals", "Move through the trunk|Keep arms as a secure hold|Breathe out during the curl", "Pulling only with arms|Sitting back instead of curling|Jerking the cable", "Dead Bug|Weighted Sit-Up");
            case "russian-twist" -> g("core", "Sit with knees bent and feet supported, holding a light ball close to the trunk.", "Rotate your ribcage and hands gently to one side, return and alternate without forcing the lower back.", "Trunk rotators and stabilisers", "Keep feet down|Use a comfortable range|Move slowly", "Swinging a heavy load|Rounding uncontrollably|Forcing rotation", "Pallof Press|Side Plank");
            case "weighted-sit-up" -> g("core", "Lie on a mat with knees bent and a small plate held securely against your chest.", "Curl the trunk up through a manageable range, then lower slowly without pulling on the neck.", "Abdominals and hip flexors", "Hold the load close|Breathe throughout|Use a controllable range", "Throwing the plate forwards|Jerking the neck|Dropping onto the mat", "Dead Bug|Cable Crunch");
            case "chin-up" -> g("pull", "Take an underhand grip on a secure bar and begin in a controlled hang.", "Pull until the chin comfortably clears the bar, then lower smoothly without swinging.", "Lats, upper back and elbow flexors", "Keep palms toward you|Keep legs controlled|Lower through a comfortable range", "Kicking to gain height|Craning the neck|Dropping the return", "Lat Pulldown|Inverted Row");
            case "neutral-grip-pull-up" -> g("pull", "Grip secure parallel handles with palms facing each other; begin in a controlled hang.", "Pull your body towards the handles, then lower smoothly without kicking or swinging.", "Lats, upper back and elbow flexors", "Check both handles|Keep the trunk steady|Lower smoothly", "Swinging to start|Reaching with the neck|Continuing after grip fails", "Lat Pulldown|Inverted Row");
            case "weighted-pull-up" -> g("pull", "Secure a modest plate to a suitable dip belt and take an overhand grip on a stable bar.", "Pull from a controlled hang until the chin clears comfortably; lower without letting the plate swing.", "Lats, upper back, elbow flexors and grip", "Check belt and chain|Keep the load still|Use a manageable addition", "Loose belt attachment|Kipping a swinging plate|Dropping the return", "Pull-Up|Lat Pulldown");
            case "weighted-chin-up" -> g("pull", "Secure a manageable dip-belt load, then grip the bar underhand with palms towards you.", "Pull upwards without swinging the plate; lower your body smoothly to a controlled hang.", "Lats, upper back, elbow flexors and grip", "Check the attachment|Keep the load steady|Control the whole return", "An unsecured plate|Kicking to finish|Losing grip under load", "Chin-Up|Lat Pulldown");
            case "inverted-row" -> g("row", "Grip a secure low bar with heels on the floor and a controlled body line beneath it.", "Pull the chest towards the bar, then extend the arms slowly without letting the hips sag.", "Upper back, lats and elbow flexors", "Check bar security|Keep the body aligned|Bend knees for an easier option", "Using an unsecured bar|Lifting only the hips|Dropping away from the bar", "Seated Cable Row|Dumbbell Row");
            case "close-grip-pulldown" -> g("pull", "Sit with thighs secured and grip a close neutral-grip handle on the high cable.", "Pull the handle to the upper chest with elbows down, then return overhead without rocking.", "Lats, upper back and elbow flexors", "Keep thighs secured|Keep trunk steady|Control the overhead return", "Leaning far backwards|Jerking the handle|Losing shoulder control", "Lat Pulldown|Neutral-Grip Pull-Up");
            case "straight-arm-pulldown" -> g("pull", "Face a high pulley, holding its bar with softly bent elbows and a braced trunk.", "Sweep the arms down towards the thighs with elbow angle nearly fixed, then return slowly.", "Lats and shoulder extensors", "Keep a small elbow bend|Keep ribs controlled|Move from the shoulders", "Turning it into a pressdown|Rocking the whole trunk|Pulling through discomfort", "Lat Pulldown|Seated Cable Row");
            case "face-pull" -> g("pull", "Set a rope pulley near face height; hold both ends and stand balanced with arms reaching forward.", "Pull the rope towards the sides of your face, separating the hands; return without leaning back.", "Rear shoulders and upper back", "Use a light load|Keep elbows comfortably high|Control the return", "Pulling towards the waist|Leaning back to lift|Forcing shoulder range", "Rear-Delt Fly|Reverse Pec Deck");
            case "pendlay-row" -> g("row", "Hinge over a bar on the floor with knees bent, a braced near-horizontal trunk and secure grip.", "Row towards the lower chest while holding the trunk angle; return the bar to the floor and reset.", "Upper back, lats and elbow flexors", "Reset before each repetition|Keep the trunk steady|Use a manageable load", "Jerking with the hips|Rounding to reach the floor|Failing to reset", "Barbell Row|Chest-Supported Row");
            case "chest-supported-row" -> g("row", "Lie chest-down on a stable inclined bench with feet supported and a dumbbell in each hand.", "Pull the weights towards the ribs, then extend the arms smoothly while keeping the chest on the pad.", "Upper back, lats and elbow flexors", "Keep chest supported|Draw elbows back|Lower smoothly", "Lifting off the bench|Shrugging to finish|Dropping the weights", "Seated Cable Row|Machine Row");
            case "t-bar-row" -> g("row", "Secure a landmine bar, straddle it and grip its row handle below the loaded end; hinge and brace.", "Pull the loaded end towards the torso, then lower smoothly without changing your trunk angle.", "Upper back, lats and elbow flexors", "Check the anchor|Keep the trunk steady|Allow room for the plates", "An unsecured landmine|Heaving with the hips|Crowding the plates against the body", "Barbell Row|Seated Cable Row");
            case "machine-row" -> g("row", "Adjust the seat and chest pad so the handles are reachable with a supported trunk.", "Draw handles towards the ribs, then return smoothly while keeping the chest against the pad.", "Upper back, lats and elbow flexors", "Adjust the machine first|Keep chest supported|Move smoothly", "Pulling away from the pad|Jerking the handles|Reaching beyond comfort", "Chest-Supported Row|Seated Cable Row");
            case "close-grip-bench-press" -> g("press", "Set bench safeties or use a spotter; grip the bar about shoulder-width with feet planted.", "Lower towards the chest with elbows comfortably beside the trunk, then press smoothly above the chest.", "Triceps, chest and front shoulders", "Keep wrists above forearms|Use a comfortable grip|Keep feet planted", "Hands touching on the bar|Bouncing off the chest|Losing support to finish", "Bench Press|Dumbbell Bench Press");
            case "wide-grip-bench-press" -> g("press", "Set safeties or use a spotter; take a moderately wider-than-shoulder grip while supported on a flat bench.", "Lower the bar through a comfortable chest range, then press without bouncing or forcing shoulder depth.", "Chest, triceps and front shoulders", "Choose a comfortable grip width|Keep shoulders supported|Control the lowering", "An excessively wide grip|Bouncing the bar|Forcing an uncomfortable bottom position", "Bench Press|Dumbbell Bench Press");
            case "incline-bench-press" -> g("press", "Set a moderate bench incline and suitable safeties; support your head and back with feet planted.", "Lower the bar towards the upper chest, then press above it with wrists supported beneath the bar.", "Upper chest, front shoulders and triceps", "Keep feet planted|Keep the bar controlled|Use a manageable incline", "Overarching off the bench|Lowering behind the shoulders|Bouncing at the chest", "Incline Dumbbell Press|Bench Press");
            case "decline-bench-press" -> g("press", "Use a slightly declined bench with secure leg supports and suitable safeties or a spotter.", "Lower towards the lower chest and press smoothly; keep body and feet securely supported throughout.", "Chest and triceps", "Check leg supports|Use a spotter for unracking|Lower smoothly", "Unsecured feet|Straining to unrack alone|Bouncing the bar", "Bench Press|Machine Chest Press");
            case "decline-dumbbell-press" -> g("press", "Secure your feet on a slightly declined bench and get help positioning the dumbbells if needed.", "Lower weights beside the chest, then press smoothly; finish by setting the weights down with assistance if required.", "Chest and triceps", "Keep both weights controlled|Keep feet secured|Plan safe setup and exit", "Losing balance while handling weights|Dropping a weight towards the face|Excessive shoulder depth", "Dumbbell Bench Press|Machine Chest Press");
            case "machine-chest-press" -> g("press", "Adjust the seat so handles sit near chest height; keep your back supported and feet stable.", "Press handles forwards, then return through a comfortable range without letting the resistance snap back.", "Chest, triceps and front shoulders", "Adjust the seat first|Keep wrists comfortable|Use a controlled return", "Lifting away from the backrest|Jerking the handles|Forcing shoulder range", "Dumbbell Bench Press|Push-Up");
            case "smith-machine-bench-press" -> g("press", "Position a flat bench beneath the Smith bar; set safety stops, check the hooks and plant your feet.", "Unrack securely, lower towards the chest along the rails and press; re-engage the hooks deliberately.", "Chest, triceps and front shoulders", "Check bench and rail alignment|Set the stops|Practise the release with light load", "Unfamiliar locking mechanism|No safety stop|Forcing an uncomfortable fixed path", "Bench Press|Machine Chest Press");
            case "weighted-push-up" -> g("press", "Fit and secure a manageable weighted vest, then set up with hands supported and body aligned.", "Lower your aligned body and press up smoothly; use an unloaded version if the vest cannot stay secure.", "Chest, triceps and trunk", "Keep the load secure|Keep hips aligned|Stop before control fades", "An unsecured vest|Using excessive load|Sagging to finish", "Push-Up|Dumbbell Bench Press");
            case "dip" -> g("press", "Grip stable parallel bars and support your body with feet clear of the floor.", "Bend the elbows to lower through a comfortable depth, then press back up without swinging.", "Triceps, chest and front shoulders", "Keep shoulders controlled|Use a comfortable depth|Lower smoothly", "Dropping too deep|Swinging the legs|Continuing through shoulder discomfort", "Push-Up|Machine Chest Press");
            case "weighted-dip" -> g("press", "Secure a manageable dip-belt load and take support on stable parallel bars with the plate clear below.", "Lower through a controlled comfortable depth and press up, keeping the plate from swinging.", "Triceps, chest and front shoulders", "Check belt and chain|Keep the plate steady|Use a modest addition", "Loose weight attachment|Forcing shoulder depth|Kicking to finish", "Dip|Close-Grip Bench Press");
            case "cable-fly" -> g("fly", "Set opposing pulleys near shoulder height; hold both handles with softly bent elbows and a stable stance.", "Bring the hands together in front of the chest in a controlled arc, then open only through a comfortable range.", "Chest and front shoulders", "Keep the elbow angle steady|Keep ribs controlled|Use light manageable resistance", "Turning it into a press|Overstretching the shoulders|Leaning forwards to finish", "Pec Deck|Dumbbell Fly");
            case "pec-deck" -> g("fly", "Sit with your back against the pad; adjust the arm pads so shoulders can move comfortably.", "Bring the pads together in front of the chest, then open them slowly without losing back support.", "Chest and front shoulders", "Adjust the starting width|Keep back supported|Control both directions", "Forcing an excessive stretch|Slamming the pads together|Lifting off the seat", "Cable Fly|Dumbbell Fly");
            default -> null;
        };
    }

    private static TechniqueGuide g(String pattern, String setup, String movement, String muscles,
                                    String cues, String mistakes, String alternatives) {
        return new TechniqueGuide(pattern, setup, movement, List.of(cues.split("\\|")),
                List.of(mistakes.split("\\|")), muscles, List.of(alternatives.split("\\|")));
    }
}
